    "+import copy",
    " import unittest",
    " from runstats import count_succeeded",
    " ",
    " ",
    " class CountSucceededTest(unittest.TestCase):",
    "     def test_empty_input_is_zero(self):",
    "         self.assertEqual(count_succeeded([]), 0)",
    "+",
    "+    def test_mixed_input_counts_only_two_successes(self):",
    "+        rows = [",
    "+            {\"outcome\": \"succeeded\"},",
    "+            {\"outcome\": \"failed\"},",
    "+            {\"outcome\": \"unknown\"},",
    "+            {\"outcome\": \"verification_failed\"},",
    "+            {},",
    "+            {\"plan\": \"complete\"},",
    "+            {\"outcome\": \"Succeeded\"},",
    "+            {\"outcome\": \"succeeded \"},",
    "+            None,",
    "+            7,",
    "+            \"succeeded\",",
    "+            {\"outcome\": \"succeeded\"},",
    "+        ]",
    "+        self.assertEqual(count_succeeded(rows), 2)",
    "+",
    "+    def test_other_outcomes_and_missing_outcome_are_excluded(self):",
    "+        for row in [",
    "+            {\"outcome\": \"failed\"},",
    "+            {\"outcome\": \"unknown\"},",
    "+            {\"outcome\": \"verification_failed\"},",
    "+            {},",
    "+            {\"plan\": \"complete\"},",
    "+        ]:",
    "+            with self.subTest(row=row):",
    "+                self.assertEqual(count_succeeded([row]), 0)",
    "+",
    "+    def test_non_dictionary_rows_are_excluded(self):",
    "+        for row in [",
    "+            None, 7, 1.5, True, \"succeeded\", [],",
    "+            [\"succeeded\"], (\"succeeded\",), {\"succeeded\"},",
    "+        ]:",
    "+            with self.subTest(row=row):",
    "+                self.assertEqual(count_succeeded([row]), 0)",
    "+",
    "+    def test_invalid_outcome_types_are_excluded(self):",
    "+        for outcome in [None, 7, 1.5, True, [], {}, [\"succeeded\"]]:",
    "+            with self.subTest(outcome=outcome):",
    "+                self.assertEqual(count_succeeded([{\"outcome\": outcome}]), 0)",
    "+",
    "+    def test_outcome_case_and_whitespace_must_match(self):",
    "+        for outcome in [",
    "+            \"Succeeded\", \"SUCCEEDED\", \"succeeded \", \" succeeded\",",
    "+            \"succeeded\\n\", \"succeeded\\t\", \"\",",
    "+        ]:",
    "+            with self.subTest(outcome=outcome):",
    "+                self.assertEqual(count_succeeded([{\"outcome\": outcome}]), 0)",
